package net.civeira.phylax.features.document.snippet.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.SnippetBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class SnippetBatchController implements SnippetBatchApi {

  /**
   * Snippet
   *
   * @autogenerated BatchControllerGenerator
   */
  private final SnippetDeleteController deleteController;

  /**
   * Disable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final SnippetDisableController disableController;

  /**
   * Enable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final SnippetEnableController enableController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response snippetApiBatchDelete(final List<String> uids, final String search,
      final Boolean global, final String code, final String tenant, final List<String> tenants) {
    return deleteController.snippetApiBatchDelete(uids, search, global, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response snippetApiBatchDeleteQuery(final String batchId) {
    return deleteController.snippetApiBatchDeleteQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response snippetApiBatchDisable(final List<String> uids, final String search,
      final Boolean global, final String code, final String tenant, final List<String> tenants) {
    return disableController.snippetApiBatchDisable(uids, search, global, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response snippetApiBatchDisableQuery(final String batchId) {
    return disableController.snippetApiBatchDisableQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param global
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response snippetApiBatchEnable(final List<String> uids, final String search,
      final Boolean global, final String code, final String tenant, final List<String> tenants) {
    return enableController.snippetApiBatchEnable(uids, search, global, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response snippetApiBatchEnableQuery(final String batchId) {
    return enableController.snippetApiBatchEnableQuery(batchId);
  }
}
